package net.civeira.phylax.feature.template.snippetversion.infrastructure.event;

import jakarta.enterprise.context.ApplicationScoped;
import jakarta.enterprise.event.Event;
import lombok.RequiredArgsConstructor;
import net.civeira.phylax.feature.template.snippetversion.domain.SnippetVersion;
import net.civeira.phylax.feature.template.snippetversion.domain.event.SnippetVersionEvent;

@ApplicationScoped
@RequiredArgsConstructor
public class SnippetVersionEventDispatcher {

  /**
   * @autogenerated EventDispatcherGenerator
   */
  private final Event<SnippetVersionEvent> emitter;

  /**
   * @autogenerated EventDispatcherGenerator
   * @param entity
   */
  public void dispatch(final SnippetVersion entity) {
    entity.getRecordedEvents().forEach(emitter::fire);
  }
}
